class.description:
The server passes this request to the handler declared with [method Netw.configure_admission], after every [NetwAccountProvider] has verified. A requested [member username] does not verify an account.
[codeblocks]
[gdscript]
func admit(request: NetwJoinRequest) -> Error:
    return OK if request.account else ERR_UNAUTHORIZED
[/gdscript]
[csharp]
private Error Admit(Variant value)
{
    using var request = NetwJoinRequest.From(value);
    return string.IsNullOrEmpty(request.Account)
        ? Error.Unauthorized : Error.Ok;
}
[/csharp]
[/codeblocks]
